changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON aula TO app_backend;
GRANT USAGE, SELECT ON SEQUENCE aula_id_aula_seq TO app_backend;
GRANT SELECT ON aula TO app_readonly;

rollback.sql:
REVOKE SELECT, INSERT, UPDATE ON aula FROM app_backend;
REVOKE USAGE, SELECT ON SEQUENCE aula_id_aula_seq FROM app_backend;
REVOKE SELECT ON aula FROM app_readonly;
